describe('scratch', () => {
    test('unpriced dimension', async () => {
        //eslint-disable-next-line
        //@ts-ignore
        const invoicesService: InvoicesService = new InvoicesService();
        //eslint-disable-next-line
        //@ts-ignore
        const customerService: CustomerService = new CustomerService();
        //eslint-disable-next-line
        //@ts-ignore
        const schedulerService: SchedulerService = new SchedulerService();
        jest.spyOn(customerService, 'findUsageForCustomer').mockImplementation(
            async () =>
                ({
                    message: 'fake',
                    data: [
                        {
                            dimensionId: '123',
                            usage: [{ startTime: '', endTime: '', value: '1000' }],
                        },
                    ],
                }) as unknown as ReadCustomerUsageData,
        );
        const basicUsageOffering = {
            offeringId: '123',
            offeringName: 'foobar',
            offeringType: OfferingType.usageBased,
            currency: SupportedCurrencies.USD,
            dimensions: [],
            billingCycle: ValidBillingCycles.monthly,
        };
        const dims = [
            {
                aggregationInterval: aggregationInterval.month,
                aggregationMethod: aggregationMethod.sum,
                dimensionName: 'fakeDimensionName',
                rounding: roundingEnum.floor,
                consumptionUnit: { unit: countBasedUnits['count-based'], type: 'count' as const },
                dimensionId: '123',
                usageIncrement: '1',
            },
        ];
        const lineItems = await Offering.getLineItemsForUsage({
            customerService,
            customer: {
                customerId: 'c',
                customerName: 'n',
                paymentChannel: paymentChannel.manual,
                businessID: 'b',
                email: 'e',
                offering: basicUsageOffering,
            },
            startDate: DatetimeUtils.fifthDayOfLastMonthAtMidnight(new Date()),
            endDate: new Date(),
            customerId: 'c',
            dimensions: dims,
            businessID: 'b',
            lineItems: new InvoiceLineItems(),
            offeringInstance: Offering.getInstance(
                { ...basicUsageOffering, dimensions: dims },
                'c',
                'b',
                invoicesService,
                { freeDimensionOnInvoice: FreeDimensionOnInvoice.show } as ReadSettingsResponseData,
                schedulerService,
                customerService,
            ),
        });
        console.log(JSON.stringify(lineItems.getLineItems()));
    });
});

import { plainToInstance } from 'class-transformer';
import { validate } from 'class-validator';
import { CreateDimensionDto } from './create-dimension.dto.js';

describe('scratch dto', () => {
    test('no price no entitlement', async () => {
        const dto = plainToInstance(CreateDimensionDto, {
            dimensionName: 'foo',
            consumptionUnit: { type: 'count', unit: 'count-based' },
            usageIncrement: '1',
            rounding: 'ceiling',
        });
        const errors = await validate(dto);
        console.log('NO PRICE ERRORS', JSON.stringify(errors.map((e) => e.constraints)));
    });
    test('with price', async () => {
        const dto = plainToInstance(CreateDimensionDto, {
            dimensionName: 'foo',
            consumptionUnit: { type: 'count', unit: 'count-based' },
            usageIncrement: '1',
            rounding: 'ceiling',
            consumptionPrice: '1.00',
        });
        const errors = await validate(dto);
        console.log('WITH PRICE ERRORS', JSON.stringify(errors.map((e) => e.constraints)));
    });
});

