import { ApiProperty } from '@nestjs/swagger';
import { IsNotEmpty, IsOptional, IsString } from 'class-validator';
import { ValidateDecimalPlace } from './validateDecimalPlaces.js';

/**
 * The string which represents an unbounded upper limit for a tier.
 */
export const UNBOUNDED_TIER_UPPER_BOUND = 'inf';

/**
 * @Class
 * A single volume based pricing tier of a dimension.
 *
 * Tiers allow usage of a dimension to be billed at a different unit price
 * depending on the volume of usage which was consumed within the billing period.
 *
 * All numerical values are represented as strings in order to avoid any precision loss.
 */
export class UsageTier {
    /**
     * The position of the tier within the list of tiers of the dimension.
     * Tiers are evaluated from the lowest position to the highest position.
     * <br><br>
     * Example `"1"`
     */
    @IsString()
    @IsNotEmpty()
    @ApiProperty({
        name: 'tierPosition',
        type: String,
        example: '1',
        description:
            'The position of the tier within the list of tiers of the dimension. Tiers are ordered from the lowest position to the highest position.',
    })
    public tierPosition: string;

    /**
     * The inclusive upper bound of usage which the tier covers.
     * Either a numeric string, or the string `"inf"` for the last tier of the dimension
     * in order to cover any remaining usage.
     * <br><br>
     * Example `"1000"`
     */
    @IsString()
    @IsNotEmpty()
    @ApiProperty({
        name: 'upperBound',
        type: String,
        example: '1000',
        description:
            'The inclusive upper bound of usage covered by the tier. A numeric string, or "inf" for the final tier.',
    })
    public upperBound: string;

    /**
     * An optional friendly, human readable name for the tier.
     * When set the tier name is appended to the name of the line item on the invoice.
     * <br><br>
     * Example `"First 1000 API Calls"`
     */
    @IsOptional()
    @IsString()
    @ApiProperty({
        name: 'tierName',
        type: String,
        example: 'First 1000 API Calls',
        required: false,
        description: 'An optional friendly name for the tier which is appended to the invoice line item name.',
    })
    public tierName?: string;

    /**
     * The unit price which applies to the usage falling inside of this tier.
     * Numerical values are represented as strings to avoid precision loss.
     * <br><br>
     * The unit price is required for every tier except the first one,
     * an omitted unit price on the first tier represents a free tier.
     * <br><br>
     * Example `"0.05"`
     */
    @IsOptional()
    @IsString()
    @ValidateDecimalPlace('unitPrice')
    @ApiProperty({
        name: 'unitPrice',
        type: String,
        example: '0.05',
        required: false,
        description:
            'The unit price applied to usage inside of the tier. Required for every tier after the first one, an omitted unit price on the first tier represents a free tier.',
    })
    public unitPrice?: string;

    constructor(tier?: UsageTier) {
        if (tier) {
            const { tierPosition, upperBound, tierName, unitPrice } = tier;
            this.tierPosition = tierPosition;
            this.upperBound = upperBound;
            if (tierName !== undefined && tierName !== null) {
                this.tierName = tierName;
            }
            if (unitPrice !== undefined && unitPrice !== null) {
                this.unitPrice = unitPrice;
            }
        }
    }
}

import { Injectable } from '@nestjs/common';
import {
    ValidationArguments,
    ValidationOptions,
    registerDecorator,
    ValidatorConstraint,
    ValidatorConstraintInterface,
} from 'class-validator';
import { overageAllowedEnum } from './create-dimension.dto.js';
import { UNBOUNDED_TIER_UPPER_BOUND, UsageTier } from './usageTier.dto.js';

/**
 * The maximum amount of decimal places which is accepted for a price field.
 */
const MAXIMUM_PRICE_DECIMAL_PLACES = 8;

/**
 * A tolerance used when comparing floating point numbers,
 * needed since the bounds of the tiers are provided as numeric strings which may contain decimals.
 */
const FLOATING_POINT_TOLERANCE = 1e-9;

export type TieredDimensionLike = {
    tiers?: UsageTier[] | null;
    usageIncrement?: string | number;
    usageEntitlement?: number | 'inf' | null;
    consumptionPrice?: string | null;
    overageAllowed?: overageAllowedEnum | boolean | null;
};

/**
 * Determines if the given value is a string which represents a finite number.
 */
export const isNumericString = (value: unknown): boolean => {
    if (typeof value !== 'string' || value.trim() === '') {
        return false;
    }
    return !isNaN(Number(value)) && isFinite(Number(value));
};

const hasValidPricePrecision = (price: string): boolean => {
    const decimalPlaces = price.split('.')[1]?.length;
    if (!decimalPlaces) {
        return true;
    }
    return decimalPlaces <= MAXIMUM_PRICE_DECIMAL_PLACES;
};

const isMultipleOf = (value: number, increment: number): boolean => {
    if (!increment || !isFinite(increment)) {
        return true;
    }
    const quotient = value / increment;
    return Math.abs(quotient - Math.round(quotient)) < FLOATING_POINT_TOLERANCE;
};

/**
 * Determines if the given dimension like object contains volume based pricing tiers.
 */
export const isTieredDimension = (dimension?: TieredDimensionLike): boolean =>
    Array.isArray(dimension?.tiers) && dimension.tiers.length > 0;

/**
 * Returns the tiers of a dimension ordered by the numerical value of their tierPosition,
 * the lowest position first. The array which is passed in is never mutated.
 */
export const getSortedTiers = (tiers: UsageTier[]): UsageTier[] => {
    if (!Array.isArray(tiers)) {
        return [];
    }
    return [...tiers].sort((left, right) => Number(left?.tierPosition) - Number(right?.tierPosition));
};

/**
 * Returns the numerical representation of the upper bound of a tier,
 * `Infinity` is returned for the unbounded `"inf"` upper bound.
 */
export const tierUpperBoundToNumber = (upperBound: string): number => {
    if (upperBound === UNBOUNDED_TIER_UPPER_BOUND) {
        return Infinity;
    }
    return parseFloat(upperBound);
};

/**
 * Validates the pricing tiers of a dimension.
 *
 * @returns the reason why the tiers are invalid, or `undefined` when the tiers are valid.
 */
export const findTiersValidationError = ({
    tiers,
    usageIncrement,
    usageEntitlement,
    consumptionPrice,
    overageAllowed,
}: TieredDimensionLike): string | undefined => {
    if (tiers === undefined || tiers === null) {
        return undefined;
    }
    if (!Array.isArray(tiers)) {
        return 'tiers: must be an array of tier objects';
    }
    if (!tiers.length) {
        return 'tiers: at least one tier must be provided when tiers is set';
    }
    if (usageEntitlement !== undefined && usageEntitlement !== null) {
        return 'tiers: a tiered dimension cannot also define a usageEntitlement';
    }
    if (consumptionPrice !== undefined && consumptionPrice !== null && `${consumptionPrice}`.trim() !== '') {
        return 'tiers: a tiered dimension cannot also define a consumptionPrice, the unitPrice of each tier is used instead';
    }
    if (overageAllowed === overageAllowedEnum.true || overageAllowed === true || `${overageAllowed}` === 'true') {
        return 'tiers: a tiered dimension cannot also allow overage';
    }

    const invalidTier = tiers.find((tier) => !tier || typeof tier !== 'object');
    if (invalidTier !== undefined) {
        return 'tiers: must be an array of tier objects';
    }

    for (const tier of tiers) {
        if (!isNumericString(tier.tierPosition) || !Number.isInteger(Number(tier.tierPosition))) {
            return `tiers: tierPosition ${tier.tierPosition} is invalid, tierPosition must be an integer numeric string`;
        }
        if (tier.upperBound !== UNBOUNDED_TIER_UPPER_BOUND) {
            if (!isNumericString(tier.upperBound)) {
                return `tiers: upperBound ${tier.upperBound} is invalid, upperBound must be a numeric string or "${UNBOUNDED_TIER_UPPER_BOUND}"`;
            }
            if (parseFloat(tier.upperBound) <= 0) {
                return `tiers: upperBound ${tier.upperBound} is invalid, upperBound must be greater than 0`;
            }
        }
        if (tier.tierName !== undefined && tier.tierName !== null && typeof tier.tierName !== 'string') {
            return 'tiers: tierName must be a string';
        }
        if (tier.unitPrice !== undefined && tier.unitPrice !== null) {
            if (!isNumericString(tier.unitPrice)) {
                return `tiers: unitPrice ${tier.unitPrice} is invalid, unitPrice must be a numeric string`;
            }
            if (parseFloat(tier.unitPrice) < 0) {
                return `tiers: unitPrice ${tier.unitPrice} is invalid, unitPrice cannot be negative`;
            }
            if (!hasValidPricePrecision(tier.unitPrice)) {
                return `tiers: unitPrice cannot have more than ${MAXIMUM_PRICE_DECIMAL_PLACES} digits of precision after the decimal place`;
            }
        }
    }

    const positions = tiers.map(({ tierPosition }) => Number(tierPosition));
    if (new Set(positions).size !== positions.length) {
        return 'tiers: every tierPosition must be unique';
    }

    const sortedTiers = getSortedTiers(tiers);
    const usageIncrementValue = usageIncrement === undefined ? undefined : Number(usageIncrement);
    let previousUpperBound = 0;
    for (const [index, tier] of sortedTiers.entries()) {
        const isLastTier = index === sortedTiers.length - 1;
        if (tier.upperBound === UNBOUNDED_TIER_UPPER_BOUND) {
            if (!isLastTier) {
                return `tiers: only the tier with the highest tierPosition can have an upperBound of "${UNBOUNDED_TIER_UPPER_BOUND}"`;
            }
        } else {
            const upperBound = parseFloat(tier.upperBound);
            if (upperBound <= previousUpperBound) {
                return `tiers: upperBound values must increase without overlap, upperBound ${tier.upperBound} is not greater than the upperBound of the previous tier`;
            }
            if (
                usageIncrementValue !== undefined &&
                !isNaN(usageIncrementValue) &&
                !isMultipleOf(upperBound, usageIncrementValue)
            ) {
                return `tiers: upperBound ${tier.upperBound} must be a multiple of the usageIncrement ${usageIncrement}`;
            }
            previousUpperBound = upperBound;
        }

        if (index > 0 && (tier.unitPrice === undefined || tier.unitPrice === null)) {
            return 'tiers: unitPrice is required for every tier except the tier with the lowest tierPosition, which represents a free tier when its unitPrice is omitted';
        }
    }

    return undefined;
};

@ValidatorConstraint({ name: 'ValidateTiersRule', async: false })
@Injectable()
export class ValidateTiersRule implements ValidatorConstraintInterface {
    validate(tiers: UsageTier[] | null, args: ValidationArguments): boolean {
        const dimension = (args?.object ?? {}) as TieredDimensionLike;
        return (
            findTiersValidationError({
                tiers,
                usageIncrement: dimension.usageIncrement,
                usageEntitlement: dimension.usageEntitlement,
                consumptionPrice: dimension.consumptionPrice,
                overageAllowed: dimension.overageAllowed,
            }) === undefined
        );
    }

    defaultMessage(args: ValidationArguments): string {
        const dimension = (args?.object ?? {}) as TieredDimensionLike;
        return (
            findTiersValidationError({
                tiers: args?.value,
                usageIncrement: dimension.usageIncrement,
                usageEntitlement: dimension.usageEntitlement,
                consumptionPrice: dimension.consumptionPrice,
                overageAllowed: dimension.overageAllowed,
            }) ?? 'tiers: the pricing tiers of the dimension are invalid'
        );
    }
}

export function ValidateTiers(property: string, validationOptions?: ValidationOptions) {
    return function (object: unknown, propertyName: string) {
        registerDecorator({
            name: 'ValidateTiers',
            target: object.constructor,
            propertyName: propertyName,
            constraints: [property],
            options: validationOptions,
            validator: ValidateTiersRule,
        });
    };
}

