public transformDtoToEntityInput(
    createDimensionDto: ReadDimensionResponseData | CreateDimensionDto,
    dimensionId,
): DimensionEntity {
    const {
        consumptionUnit,
        dimensionName,
        usageIncrement,
        rounding,
        usageEntitlement,
        overageAllowed,
        consumptionPrice,
        businessID,
        aggregationInterval: argumentAggregationInternal,
        aggregationMethod: argumentAggregationMethod,
        metadata,
        tiers,
    } = createDimensionDto;
    let measurementId;

    //eslint-disable-next-line
    //@ts-ignore
    if (createDimensionDto?.measurementId === null) {
        measurementId = undefined;
    }
    //eslint-disable-next-line
    //@ts-ignore
    else if (createDimensionDto?.measurement?.measurementId) {
        //eslint-disable-next-line
        //@ts-ignore
        measurementId = createDimensionDto?.measurement?.measurementId;
    } else {
        //eslint-disable-next-line
        //@ts-ignore
        measurementId = createDimensionDto?.measurementId;
    }
    const normalizedTiers = DimensionsService.normalizeTiers(tiers);
    const isTiered = !!normalizedTiers?.length;
    if (isTiered) {
        const validationError = findTiersValidationError({
            tiers: normalizedTiers,
            usageIncrement,
            usageEntitlement,
            consumptionPrice,
            // A dimension which is read back always reports overageAllowed as false,
            // therefore only an explicitly allowed overage conflicts with the tiers.
            overageAllowed: overageAllowed === overageAllowedEnum.true ? overageAllowed : undefined,
        });
        if (validationError) {
            throw new BadRequestException(validationError);
        }
    }
    const input = {
        typeofDimension: 'numerical',
        numerical: {
            numericalType: numericalType['int'],
            dimensionUnit: consumptionUnit.unit,
            dimensionUnitType: consumptionUnit.type.toLowerCase(),
            aggregationInterval: argumentAggregationInternal
                ? argumentAggregationInternal
                : aggregationInterval['Hour'],
            aggregationMethod: argumentAggregationMethod ? argumentAggregationMethod : aggregationMethod['max'],
            priceSegments: [
                {
                    lowerLimit: '0',
                    upperLimit: 'inf',
                    price: isTiered ? undefined : consumptionPrice,
                },
            ],
            sampleType: SampleType['gauge'],
            usageIncrement,
            rounding,
            usageEntitlement: isTiered ? undefined : usageEntitlement,
            overageAllowed: isTiered ? undefined : overageAllowed,
            tiers: normalizedTiers,
        },
        businessID,
        dimensionId,
        dimensionName,
        categorical: {},
        measurementId,
        metadata,
    };
    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
    //@ts-ignore
    return input;
}

/**
 * Removes any of the fields which are not part of a tier from the given tiers,
 * and returns undefined when no tiers are set. Tiers are stored exactly as they were provided.
 */
private static normalizeTiers(tiers?: UsageTier[] | null): UsageTier[] | undefined {
    if (tiers === undefined || tiers === null) {
        return undefined;
    }
    if (!Array.isArray(tiers)) {
        throw new BadRequestException('tiers: must be an array of tier objects');
    }
    if (!tiers.length) {
        return undefined;
    }
    return tiers.map((tier) => new UsageTier(tier));
}

/**
 * Tiered pricing and the single consumption price / entitlement based pricing are mutually exclusive.
 * Whenever an update switches a dimension from one pricing model to the other one,
 * the fields of the pricing model which is being replaced are removed from the dimension.
 * Conflicting fields which are sent inside of the same request are rejected.
 */
private mergeTierPricingForUpdate(
    existingDimension: ReadDimensionResponseData,
    updatedFields: Partial<UpdateDimensionDto>,
    mergedDimension: ReadDimensionResponseData,
): ReadDimensionResponseData {
    const tiersAreUpdated = 'tiers' in (updatedFields ?? {});
    const updatedTiers = updatedFields?.tiers;
    if (tiersAreUpdated && (updatedTiers === null || (Array.isArray(updatedTiers) && !updatedTiers.length))) {
        // Passing tiers as null clears all of the tiers of the dimension
        return { ...mergedDimension, tiers: undefined };
    }
    if (tiersAreUpdated && Array.isArray(updatedTiers) && updatedTiers.length) {
        const validationError = findTiersValidationError({
            tiers: updatedTiers,
            usageIncrement: mergedDimension?.usageIncrement,
            usageEntitlement: updatedFields?.usageEntitlement,
            consumptionPrice: updatedFields?.consumptionPrice,
            overageAllowed: updatedFields?.overageAllowed,
        });
        if (validationError) {
            throw new BadRequestException(validationError);
        }
        // The tiers replace any of the pricing information which is currently set on the dimension
        return {
            ...mergedDimension,
            tiers: updatedTiers,
            consumptionPrice: undefined,
            usageEntitlement: undefined,
            overageAllowed: undefined,
        };
    }
    const replacesTiersWithConsumptionPricing =
        (updatedFields?.consumptionPrice !== undefined && updatedFields?.consumptionPrice !== null) ||
        (updatedFields?.usageEntitlement !== undefined && updatedFields?.usageEntitlement !== null);
    if (existingDimension?.tiers?.length && replacesTiersWithConsumptionPricing) {
        return { ...mergedDimension, tiers: undefined };
    }
    return mergedDimension;
}

