/**
 * Allocates the total usage of a dimension across the volume based pricing tiers of the dimension.
 *
 * The tiers are evaluated in the order of the numerical value of their tierPosition,
 * and the upperBound of every tier is inclusive, which means that a tier with an upperBound of `"1000"`
 * covers the usage from the upper bound of the previous tier up to and including 1000 units of usage.
 *
 * Only the tiers which have been consumed are returned.
 */
public static allocateUsageAcrossTiers({
    totalUsage,
    tiers,
}: {
    totalUsage: number;
    tiers: UsageTier[];
}): Array<{ tier: UsageTier; usage: number }> {
    const usage = Number.isFinite(totalUsage) && totalUsage > 0 ? totalUsage : 0;
    const allocations: Array<{ tier: UsageTier; usage: number }> = [];
    let previousUpperBound = 0;
    for (const tier of getSortedTiers(tiers)) {
        const upperBound = tierUpperBoundToNumber(tier?.upperBound);
        if (isNaN(upperBound)) {
            continue;
        }
        const usageInTier = Math.min(usage, upperBound) - previousUpperBound;
        if (isFinite(upperBound)) {
            previousUpperBound = upperBound;
        }
        if (usageInTier > 0) {
            allocations.push({ tier, usage: usageInTier });
        }
    }
    return allocations;
}

