/**
 * Converts the price of a dimension, or of one of its tiers, into the unit cost of a line item.
 * The precision of the price which was configured is preserved when the amount is converted into another currency.
 */
static convertPriceToUnitCost({ price, exchangeRate }: { price: string; exchangeRate: number }): number {
    const parsedPrice = parseFloat(price);
    const decimals = Offering.getDecimalsForNumber(parsedPrice);
    return Number((parsedPrice * exchangeRate).toFixed(decimals === 0 ? 2 : decimals));
}

/**
 * Adds one line item for every volume based pricing tier of the dimension which has been consumed.
 * The usage of the dimension is allocated across the tiers of the dimension,
 * and each of those allocations is billed at the unit price of the tier which it falls into.
 */
static addTieredLineItemsForUsage({
    dimension,
    dimensionId,
    totalUsage,
    lineItems,
    exchangeRate,
    negative,
    offeringInstance,
}: {
    dimension: ReadDimensionResponseData;
    dimensionId: string;
    totalUsage: number;
    lineItems: InvoiceLineItems;
    exchangeRate: number;
    negative?: boolean;
    offeringInstance: Offering;
}): InvoiceLineItems {
    const {
        usageIncrement,
        consumptionUnit: { unit, type },
    } = dimension;
    const allocations = Billing.allocateUsageAcrossTiers({ totalUsage, tiers: dimension.tiers });
    allocations.forEach(({ tier, usage: usageInTier }) => {
        // A tier without a unit price is a free tier
        const unitCost = Offering.convertPriceToUnitCost({
            price: tier?.unitPrice === undefined || tier?.unitPrice === null ? '0' : tier.unitPrice,
            exchangeRate,
        });
        if (!Number.isFinite(unitCost)) {
            Offering.logger.log(
                `Tier ${tier?.tierPosition} of dimension ${dimensionId} has an invalid unit price, skipping the line item`,
            );
            return;
        }
        const shouldDisplayLineItem = Billing.determineIfLineItemShown({
            Offering: offeringInstance,
