import { plainToInstance } from 'class-transformer';
import { validate } from 'class-validator';
import {
    CreateDimensionDto,
    countBasedUnits,
    overageAllowedEnum,
    roundingEnum,
} from '../dto/create-dimension.dto.js';
import { UpdateDimensionDto } from '../dto/update-dimension.dto.js';
import { findTiersValidationError, getSortedTiers, isTieredDimension } from '../dto/tiersValidator.js';

const baseDimension = {
    dimensionName: 'API Call',
    consumptionUnit: { type: 'count', unit: countBasedUnits['count-based'] },
    usageIncrement: '1',
    rounding: roundingEnum.ceiling,
};

const validateDimension = async (dimension: Record<string, unknown>) => {
    const dto = plainToInstance(CreateDimensionDto, dimension);
    return validate(dto);
};

const getConstraintKeys = (errors: Awaited<ReturnType<typeof validate>>) =>
    errors.map(({ property, constraints }) => ({ property, keys: Object.keys(constraints ?? {}) }));

describe('Dimension pricing tiers', () => {
    describe('CreateDimensionDto validation', () => {
        test('accepts a dimension with tiers and no consumption price', async () => {
            const errors = await validateDimension({
                ...baseDimension,
                tiers: [
                    { tierPosition: '1', upperBound: '1000', tierName: 'First 1000', unitPrice: '0.05' },
                    { tierPosition: '2', upperBound: 'inf', tierName: 'Remaining', unitPrice: '0.03' },
                ],
            });
            expect(getConstraintKeys(errors)).toEqual([]);
        });
        test('accepts an omitted unit price on the first tier as a free tier', async () => {
            const errors = await validateDimension({
                ...baseDimension,
                tiers: [
                    { tierPosition: '1', upperBound: '1000' },
                    { tierPosition: '2', upperBound: 'inf', unitPrice: '0.03' },
                ],
            });
            expect(errors).toEqual([]);
        });
        test('accepts a dimension without tiers, consumption price is still required', async () => {
            const withPrice = await validateDimension({ ...baseDimension, consumptionPrice: '20.00' });
            expect(withPrice).toEqual([]);
        });
        test('rejects an omitted unit price on any tier after the first tier', async () => {
            const errors = await validateDimension({
                ...baseDimension,
                tiers: [
                    { tierPosition: '1', upperBound: '1000', unitPrice: '0.05' },
                    { tierPosition: '2', upperBound: 'inf' },
                ],
            });
            expect(errors.length).toBeGreaterThan(0);
            expect(JSON.stringify(errors)).toContain('unitPrice is required');
        });
        test('rejects overlapping upper bounds', async () => {
            const errors = await validateDimension({
                ...baseDimension,
                tiers: [
                    { tierPosition: '1', upperBound: '1000', unitPrice: '0.05' },
                    { tierPosition: '2', upperBound: '500', unitPrice: '0.03' },
                ],
            });
            expect(JSON.stringify(errors)).toContain('without overlap');
        });
        test('rejects upper bounds which are not aligned to the usage increment', async () => {
            const errors = await validateDimension({
                ...baseDimension,
                usageIncrement: '100',
                tiers: [
                    { tierPosition: '1', upperBound: '150', unitPrice: '0.05' },
                    { tierPosition: '2', upperBound: 'inf', unitPrice: '0.03' },
                ],
            });
            expect(JSON.stringify(errors)).toContain('multiple of the usageIncrement');
        });
        test('accepts upper bounds which are aligned to the usage increment', async () => {
            const errors = await validateDimension({
                ...baseDimension,
                usageIncrement: '100',
                tiers: [
                    { tierPosition: '1', upperBound: '1000', unitPrice: '0.05' },
                    { tierPosition: '2', upperBound: 'inf', unitPrice: '0.03' },
                ],
            });
            expect(errors).toEqual([]);
        });
        test('rejects an unbounded tier which is not the last tier', async () => {
            const errors = await validateDimension({
                ...baseDimension,
                tiers: [
                    { tierPosition: '1', upperBound: 'inf', unitPrice: '0.05' },
                    { tierPosition: '2', upperBound: '2000', unitPrice: '0.03' },
                ],
            });
            expect(JSON.stringify(errors)).toContain('only the tier with the highest tierPosition');
        });
        test('rejects tiers combined with a usage entitlement', async () => {
            const errors = await validateDimension({
                ...baseDimension,
                usageEntitlement: 1000,
                tiers: [{ tierPosition: '1', upperBound: 'inf', unitPrice: '0.05' }],
            });
            expect(JSON.stringify(errors)).toContain('cannot also define a usageEntitlement');
        });
        test('rejects tiers combined with a consumption price', async () => {
            const errors = await validateDimension({
                ...baseDimension,
                consumptionPrice: '20.00',
                tiers: [{ tierPosition: '1', upperBound: 'inf', unitPrice: '0.05' }],
            });
            expect(JSON.stringify(errors)).toContain('cannot also define a consumptionPrice');
        });
        test('rejects tiers combined with allowed overage', async () => {
            const errors = await validateDimension({
                ...baseDimension,
                overageAllowed: overageAllowedEnum.true,
                tiers: [{ tierPosition: '1', upperBound: 'inf', unitPrice: '0.05' }],
            });
            expect(JSON.stringify(errors)).toContain('cannot also allow overage');
        });
        test('rejects a unit price with more than eight decimal places', async () => {
            const errors = await validateDimension({
                ...baseDimension,
                tiers: [{ tierPosition: '1', upperBound: 'inf', unitPrice: '0.0000000001' }],
            });
            expect(errors.length).toBeGreaterThan(0);
        });
        test('rejects an empty tiers array', async () => {
            const errors = await validateDimension({ ...baseDimension, tiers: [] });
            expect(JSON.stringify(errors)).toContain('at least one tier');
        });
        test('allows tiers to be cleared with null on an update', async () => {
            const dto = plainToInstance(UpdateDimensionDto, { tiers: null });
            expect(await validate(dto)).toEqual([]);
        });
    });

    describe('findTiersValidationError', () => {
        test('returns undefined when no tiers are set', () => {
            expect(findTiersValidationError({})).toBeUndefined();
            expect(findTiersValidationError({ tiers: null, consumptionPrice: '1.00' })).toBeUndefined();
        });
        test('does not treat overageAllowed false as a conflict', () => {
            expect(
                findTiersValidationError({
                    tiers: [{ tierPosition: '1', upperBound: 'inf', unitPrice: '0.05' }],
                    usageIncrement: '1',
                    overageAllowed: overageAllowedEnum.false,
                }),
            ).toBeUndefined();
        });
        test('rejects duplicated tier positions', () => {
            expect(
                findTiersValidationError({
                    tiers: [
                        { tierPosition: '1', upperBound: '10', unitPrice: '0.05' },
                        { tierPosition: '1', upperBound: '20', unitPrice: '0.05' },
                    ],
                    usageIncrement: '1',
                }),
            ).toContain('unique');
        });
    });

    describe('tier helpers', () => {
        test('sorts the tiers by the numerical value of the tier position', () => {
            const tiers = [
                { tierPosition: '10', upperBound: 'inf', unitPrice: '0.01' },
                { tierPosition: '2', upperBound: '2000', unitPrice: '0.03' },
                { tierPosition: '1', upperBound: '1000', unitPrice: '0.05' },
            ];
            expect(getSortedTiers(tiers).map(({ tierPosition }) => tierPosition)).toEqual(['1', '2', '10']);
            // the original array is not mutated
            expect(tiers[0].tierPosition).toEqual('10');
        });
        test('detects tiered dimensions', () => {
            expect(isTieredDimension({ tiers: [{ tierPosition: '1', upperBound: 'inf' }] })).toEqual(true);
            expect(isTieredDimension({ tiers: [] })).toEqual(false);
            expect(isTieredDimension({})).toEqual(false);
            expect(isTieredDimension(undefined)).toEqual(false);
        });
    });
});

import { Test, TestingModule } from '@nestjs/testing';
import { createMock } from '@golevelup/ts-jest';
import { BadRequestException } from '@nestjs/common';
import { DimensionsService } from './dimensions.service.js';
import { InfluxService } from '../influx/influx.service.js';
import { countBasedUnits, CreateDimensionDto, roundingEnum } from './dto/create-dimension.dto.js';
import { UsageTier } from './dto/usageTier.dto.js';

describe('DimensionsService pricing tiers', () => {
    let service: DimensionsService;
    let storedTags: Record<string, string>;
    let storedFields: Record<string, string>;
    const loadPoints = jest.fn();

    const influxServiceMock = () => ({
        loadPoints,
        getPoint: () => ({
            tag: (key: string, value: string) => {
                storedTags[key] = value;
            },
            stringField: (key: string, value: string) => {
                storedFields[key] = value;
            },
        }),
        getSingleDimension: async () => [{ ...storedTags, _value: storedFields.dimensionName }],
        dropDimensionConfig: async () => undefined,
    });

    const tiers: UsageTier[] = [
        { tierPosition: '1', upperBound: '1000', tierName: 'First 1000', unitPrice: '0.05' },
        { tierPosition: '2', upperBound: 'inf', tierName: 'Remaining', unitPrice: '0.03' },
    ];

    const dimensionWithTiers = {
        businessID: 'fakeBusinessID',
        dimensionName: 'API Call',
        usageIncrement: '1',
        rounding: roundingEnum.ceiling,
        consumptionUnit: { type: 'count', unit: countBasedUnits['count-based'] },
        tiers,
    } as unknown as CreateDimensionDto;

    beforeEach(async () => {
        storedTags = {};
        storedFields = {};
        const module: TestingModule = await Test.createTestingModule({
            providers: [DimensionsService],
        })
            .useMocker((token) => {
                if (token === InfluxService) {
                    return influxServiceMock();
                }
                return createMock();
            })
            .compile();

        service = module.get<DimensionsService>(DimensionsService);
    });

    afterEach(() => {
        jest.clearAllMocks();
    });

    test('persists the tiers of a dimension when it is created', async () => {
        const { dimensionId } = await service.create({ ...dimensionWithTiers }, 'fakeSubject');
        expect(dimensionId).toBeDefined();
        expect(loadPoints).toHaveBeenCalledTimes(1);
        expect(JSON.parse(storedTags.tiers)).toEqual(tiers);
        // A tiered dimension never carries a consumption price
        expect(JSON.parse(storedTags.priceSegments)[0].price).toBeUndefined();
    });

    test('returns the same tiers when the dimension is read back', async () => {
        const { dimensionId } = await service.create({ ...dimensionWithTiers }, 'fakeSubject');
        const {
            data: [dimension],
        } = await service.findOne({ dimensionId, businessID: 'fakeBusinessID' });
        expect(dimension.tiers).toEqual(tiers);
        expect(dimension.consumptionPrice).toBeUndefined();
        expect(dimension.usageEntitlement).toBeUndefined();
    });

    test('does not attach tiers to dimensions which do not define any', async () => {
        const { dimensionId } = await service.create(
            {
                ...dimensionWithTiers,
                tiers: undefined,
                consumptionPrice: '20.00',
            } as unknown as CreateDimensionDto,
            'fakeSubject',
        );
        expect(storedTags.tiers).toBeUndefined();
        const {
            data: [dimension],
        } = await service.findOne({ dimensionId, businessID: 'fakeBusinessID' });
        expect(dimension.tiers).toBeUndefined();
        expect(dimension.consumptionPrice).toEqual('20.00');
    });

    test('rejects the creation of a dimension with invalid tiers', async () => {
        await expect(
            service.create(
                {
                    ...dimensionWithTiers,
                    tiers: [
                        { tierPosition: '1', upperBound: '1000', unitPrice: '0.05' },
                        { tierPosition: '2', upperBound: '500', unitPrice: '0.03' },
                    ],
                } as unknown as CreateDimensionDto,
                'fakeSubject',
            ),
        ).rejects.toThrow(BadRequestException);
    });

    test('replaces the tiers of a dimension on an update', async () => {
        const { dimensionId } = await service.create({ ...dimensionWithTiers }, 'fakeSubject');
        const replacementTiers = [
            { tierPosition: '1', upperBound: '500', unitPrice: '0.08' },
            { tierPosition: '2', upperBound: 'inf', unitPrice: '0.01' },
        ];
        await service.update({ dimensionId, businessID: 'fakeBusinessID', tiers: replacementTiers }, 'fakeSubject');
        const {
            data: [dimension],
        } = await service.findOne({ dimensionId, businessID: 'fakeBusinessID' });
        expect(dimension.tiers).toEqual(replacementTiers);
    });

    test('clears the tiers of a dimension when tiers is set to null', async () => {
        const { dimensionId } = await service.create({ ...dimensionWithTiers }, 'fakeSubject');
        await service.update({ dimensionId, businessID: 'fakeBusinessID', tiers: null }, 'fakeSubject');
        const {
            data: [dimension],
        } = await service.findOne({ dimensionId, businessID: 'fakeBusinessID' });
        expect(dimension.tiers).toBeUndefined();
        expect(dimension.consumptionPrice).toBeUndefined();
        expect(dimension.usageEntitlement).toBeUndefined();
    });

    test('replaces the consumption price of a dimension with tiers on an update', async () => {
        const { dimensionId } = await service.create(
            {
                ...dimensionWithTiers,
                tiers: undefined,
                consumptionPrice: '20.00',
            } as unknown as CreateDimensionDto,
            'fakeSubject',
        );
        await service.update({ dimensionId, businessID: 'fakeBusinessID', tiers }, 'fakeSubject');
        const {
            data: [dimension],
        } = await service.findOne({ dimensionId, businessID: 'fakeBusinessID' });
        expect(dimension.tiers).toEqual(tiers);
        expect(dimension.consumptionPrice).toBeUndefined();
    });

    test('rejects an update which sets both tiers and a consumption price', async () => {
        const { dimensionId } = await service.create({ ...dimensionWithTiers }, 'fakeSubject');
        await expect(
            service.update(
                { dimensionId, businessID: 'fakeBusinessID', tiers, consumptionPrice: '20.00' },
                'fakeSubject',
            ),
        ).rejects.toThrow(BadRequestException);
    });

    test('rejects an update which sets both tiers and a usage entitlement', async () => {
        const { dimensionId } = await service.create({ ...dimensionWithTiers }, 'fakeSubject');
        await expect(
            service.update({ dimensionId, businessID: 'fakeBusinessID', tiers, usageEntitlement: 1000 }, 'fakeSubject'),
        ).rejects.toThrow(BadRequestException);
    });

    test('rejects an update with tiers which are not aligned to the usage increment of the dimension', async () => {
        const { dimensionId } = await service.create(
            { ...dimensionWithTiers, tiers: undefined, consumptionPrice: '1.00', usageIncrement: '100' },
            'fakeSubject',
        );
        await expect(
            service.update(
                {
                    dimensionId,
                    businessID: 'fakeBusinessID',
                    tiers: [
                        { tierPosition: '1', upperBound: '150', unitPrice: '0.05' },
                        { tierPosition: '2', upperBound: 'inf', unitPrice: '0.03' },
                    ],
                },
                'fakeSubject',
            ),
        ).rejects.toThrow(BadRequestException);
    });
});

