import { CustomerService } from '../../customer/customer.service.js';
import { paymentChannel } from '../../customer/dto/create-customer.dto.js';
import { ReadCustomerUsageData } from '../../customer/dto/read-customer.dto.js';
import { ReadCustomerResponseData } from '../../customer/entities/customer.entity.js';
import {
    aggregationInterval,
    aggregationMethod,
    countBasedUnits,
    roundingEnum,
} from '../../dimensions/dto/create-dimension.dto.js';
import { ReadDimensionResponseData } from '../../dimensions/dto/read-dimension.dto.js';
import { UsageTier } from '../../dimensions/dto/usageTier.dto.js';
import { InvoiceLineItem, InvoiceLineItems } from '../../invoice/entities/invoice.entity.js';
import { InvoicesService } from '../../invoice/invoices.service.js';
import { SchedulerService } from '../../scheduler/scheduler.service.js';
import { FreeDimensionOnInvoice } from '../../setting/dto/FreeDimensionOnInvoice.js';
import { ReadSettingsResponseData } from '../../setting/dto/read-setting.dto.js';
import { DatetimeUtils } from '../../utils/datetime.js';
import { ValidBillingCycles } from '../dto/createOffering.dto.js';
import { ReadOfferingResponseData } from '../dto/readOffering.dto.js';
import { SupportedCurrencies } from '../dto/SupportedCurrencies.js';
import { Offering } from './offeringPackage.entity.js';
import { OfferingType } from './OfferingType.js';
import { Billing } from '../../billing/entities/billing.entity.js';

jest.mock('../../analytics/analytics.service', () => ({
    AnalyticsService: {
        getExchangeRate: jest.fn(() => 0.91),
    },
}));

describe('Tiered usage line items', () => {
    let invoicesService: InvoicesService;
    let customerService: CustomerService;
    let schedulerService: SchedulerService;
    const fakeBusinessID = 'fakeBusinessID';
    const fakeCustomerID = 'fakeCustomerID';
    const dimensionId = '123';

    const usageBasedOffering: ReadOfferingResponseData = {
        offeringId: '123',
        offeringName: 'foobar',
        offeringType: OfferingType.usageBased,
        currency: SupportedCurrencies.USD,
        dimensions: [],
        billingCycle: ValidBillingCycles.monthly,
    };

    const tieredDimension = (
        tiers: UsageTier[],
        overrides: Partial<ReadDimensionResponseData> = {},
    ): ReadDimensionResponseData =>
        ({
            dimensionId,
            dimensionName: 'fakeDimensionName',
            aggregationInterval: aggregationInterval.month,
            aggregationMethod: aggregationMethod.sum,
            usageIncrement: '1',
            rounding: roundingEnum.floor,
            consumptionUnit: { unit: countBasedUnits['count-based'], type: 'count' },
            tiers,
            ...overrides,
        }) as ReadDimensionResponseData;

    const mockUsage = (value: string) => {
        jest.spyOn(customerService, 'findUsageForCustomer').mockImplementation(
            async () =>
                ({
                    message: 'fake',
                    data: [
                        {
                            dimensionId,
                            usage: [
                                {
                                    startTime: DatetimeUtils.beginningOfDay(new Date()).toISOString(),
                                    endTime: DatetimeUtils.endOfDay(new Date()).toISOString(),
                                    value,
                                },
                            ],
                        },
                    ],
                }) as unknown as ReadCustomerUsageData,
        );
    };

    const getLineItems = async ({
        dimension,
        currency = SupportedCurrencies.USD,
        freeDimensionOnInvoice = FreeDimensionOnInvoice.show,
    }: {
        dimension: ReadDimensionResponseData;
        currency?: SupportedCurrencies;
        freeDimensionOnInvoice?: FreeDimensionOnInvoice;
    }) => {
        const customer = {
            customerId: fakeCustomerID,
            customerName: 'fakeCustomerName',
            paymentChannel: paymentChannel.manual,
            businessID: fakeBusinessID,
            email: 'fakeEmail',
            currency,
            offering: usageBasedOffering,
            invoices: [],
        } as unknown as ReadCustomerResponseData;
        const lineItems = await Offering.getLineItemsForUsage({
            customerService,
            customer,
            startDate: DatetimeUtils.fifthDayOfLastMonthAtMidnight(new Date()),
            endDate: new Date(),
            customerId: fakeCustomerID,
            dimensions: [dimension],
            businessID: fakeBusinessID,
            lineItems: new InvoiceLineItems(),
            offeringInstance: Offering.getInstance(
                { ...usageBasedOffering, dimensions: [dimension] },
                fakeCustomerID,
                fakeBusinessID,
                invoicesService,
                { freeDimensionOnInvoice } as ReadSettingsResponseData,
                schedulerService,
                customerService,
            ),
        });
        return lineItems.getLineItems();
    };

    beforeEach(() => {
        jest.useFakeTimers('modern').setSystemTime(new Date('2023-08-16'));
        //eslint-disable-next-line
        //@ts-ignore
        invoicesService = new InvoicesService();
        //eslint-disable-next-line
        //@ts-ignore
        customerService = new CustomerService();
        //eslint-disable-next-line
        //@ts-ignore
        schedulerService = new SchedulerService();
        //eslint-disable-next-line
        //@ts-ignore
        jest.spyOn(customerService, 'findUsageForCustomer').mockImplementation(async () => ({}));
    });

    afterEach(() => {
        jest.clearAllMocks();
        jest.useRealTimers();
    });

    describe('Billing.allocateUsageAcrossTiers', () => {
        const tiers: UsageTier[] = [
            { tierPosition: '2', upperBound: '2000', unitPrice: '0.03' },
            { tierPosition: '1', upperBound: '1000', unitPrice: '0.05' },
            { tierPosition: '3', upperBound: 'inf', unitPrice: '0.01' },
        ];
        test('allocates the usage across the inclusive bounds of the tiers ordered by tier position', () => {
            expect(Billing.allocateUsageAcrossTiers({ totalUsage: 2500, tiers })).toEqual([
                { tier: tiers[1], usage: 1000 },
                { tier: tiers[0], usage: 1000 },
                { tier: tiers[2], usage: 500 },
            ]);
        });
        test('only returns the tiers which have been consumed', () => {
            expect(Billing.allocateUsageAcrossTiers({ totalUsage: 1000, tiers })).toEqual([
                { tier: tiers[1], usage: 1000 },
            ]);
            expect(Billing.allocateUsageAcrossTiers({ totalUsage: 0, tiers })).toEqual([]);
        });
        test('does not bill usage beyond the highest bounded tier', () => {
            const boundedTiers: UsageTier[] = [{ tierPosition: '1', upperBound: '100', unitPrice: '0.05' }];
            expect(Billing.allocateUsageAcrossTiers({ totalUsage: 250, tiers: boundedTiers })).toEqual([
                { tier: boundedTiers[0], usage: 100 },
            ]);
        });
    });

    test('creates one line item per consumed tier', async () => {
        mockUsage('1500');
        const lineItems = await getLineItems({
            dimension: tieredDimension([
                { tierPosition: '1', upperBound: '1000', tierName: 'First 1000', unitPrice: '0.05' },
                { tierPosition: '2', upperBound: 'inf', tierName: 'Remaining', unitPrice: '0.03' },
            ]),
        });
        expect(lineItems).toEqual([
            expect.objectContaining(
                new InvoiceLineItem('fakeDimensionName - foobar - First 1000', 1000, 0.05, undefined),
            ),
            expect.objectContaining(new InvoiceLineItem('fakeDimensionName - foobar - Remaining', 500, 0.03, undefined)),
        ]);
    });

    test('orders the line items by the numerical value of the tier position', async () => {
        mockUsage('2500');
        const lineItems = await getLineItems({
            dimension: tieredDimension([
                { tierPosition: '10', upperBound: 'inf', tierName: 'Tier ten', unitPrice: '0.01' },
                { tierPosition: '2', upperBound: '2000', tierName: 'Tier two', unitPrice: '0.03' },
                { tierPosition: '1', upperBound: '1000', tierName: 'Tier one', unitPrice: '0.05' },
            ]),
        });
        expect(lineItems.map(({ name, quantity, unitCost }) => ({ name, quantity, unitCost }))).toEqual([
            { name: 'fakeDimensionName - foobar - Tier one', quantity: 1000, unitCost: 0.05 },
            { name: 'fakeDimensionName - foobar - Tier two', quantity: 1000, unitCost: 0.03 },
            { name: 'fakeDimensionName - foobar - Tier ten', quantity: 500, unitCost: 0.01 },
        ]);
    });

    test('uses the normal line item name when the tier has no name', async () => {
        mockUsage('500');
        const lineItems = await getLineItems({
            dimension: tieredDimension([{ tierPosition: '1', upperBound: 'inf', unitPrice: '0.05' }]),
        });
        expect(lineItems.map(({ name }) => name)).toEqual(['fakeDimensionName - foobar']);
    });

    test('divides the quantity of every tier by the usage increment of the dimension', async () => {
        mockUsage('1500');
        const lineItems = await getLineItems({
            dimension: tieredDimension(
                [
                    { tierPosition: '1', upperBound: '1000', unitPrice: '0.05' },
                    { tierPosition: '2', upperBound: 'inf', unitPrice: '0.03' },
                ],
                { usageIncrement: '10' },
            ),
        });
        expect(lineItems.map(({ quantity, unitCost }) => ({ quantity, unitCost }))).toEqual([
            { quantity: 100, unitCost: 0.05 },
            { quantity: 50, unitCost: 0.03 },
        ]);
    });

    test('bills an omitted unit price on the first tier as a free tier', async () => {
        mockUsage('1500');
        const dimension = tieredDimension([
            { tierPosition: '1', upperBound: '1000', tierName: 'Included' },
            { tierPosition: '2', upperBound: 'inf', tierName: 'Overage', unitPrice: '0.03' },
        ]);
        expect(
            (await getLineItems({ dimension })).map(({ name, quantity, unitCost }) => ({ name, quantity, unitCost })),
        ).toEqual([
            { name: 'fakeDimensionName - foobar - Included', quantity: 1000, unitCost: 0 },
            { name: 'fakeDimensionName - foobar - Overage', quantity: 500, unitCost: 0.03 },
        ]);
        // Free tiers follow the freeDimensionOnInvoice setting
        expect(
            (await getLineItems({ dimension, freeDimensionOnInvoice: FreeDimensionOnInvoice.hide })).map(
                ({ name }) => name,
            ),
        ).toEqual(['fakeDimensionName - foobar - Overage']);
    });

    test('preserves the precision of the tier prices when the currency is converted', async () => {
        mockUsage('1500');
        const lineItems = await getLineItems({
            dimension: tieredDimension([
                { tierPosition: '1', upperBound: '1000', unitPrice: '1.23456789' },
                { tierPosition: '2', upperBound: 'inf', unitPrice: '1.00' },
            ]),
            currency: SupportedCurrencies.EUR,
        });
        expect(lineItems.map(({ quantity, unitCost }) => ({ quantity, unitCost }))).toEqual([
            // 1.12345678 = 0.91 * 1.23456789, the exchange rate of the mock is 0.91
            { quantity: 1000, unitCost: 1.12345678 },
            { quantity: 500, unitCost: 0.91 },
        ]);
    });

    test('does not create line items for a dimension without tiers and without a consumption price', async () => {
        mockUsage('1500');
        const lineItems = await getLineItems({
            dimension: tieredDimension(undefined, { tiers: undefined }),
        });
        expect(lineItems).toEqual([]);
    });

    test('keeps billing dimensions which have a consumption price and no tiers unchanged', async () => {
        mockUsage('1500');
        const lineItems = await getLineItems({
            dimension: tieredDimension(undefined, { tiers: undefined, consumptionPrice: '0.05' }),
        });
        expect(lineItems.map(({ name, quantity, unitCost }) => ({ name, quantity, unitCost }))).toEqual([
            { name: 'fakeDimensionName - foobar', quantity: 1500, unitCost: 0.05 },
        ]);
    });
});

